const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const dir = "/w/covexclude";
fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
function write(file, text) {
  const p = path.join(dir, file);
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, text);
}
const outFile = path.join(dir, "included.json");
// A custom coverage provider built on vitest/node's BaseCoverageProvider: it reports
// whether src/component.js passes coverage.include minus coverage.exclude.
write("provider.mjs", [
  "import { writeFileSync } from 'node:fs'",
  "export default {",
  "  async getProvider() {",
  "    const { BaseCoverageProvider } = await import('vitest/node')",
  "    class Probe extends BaseCoverageProvider {",
  "      name = 'custom'",
  "      initialize(ctx) { this.version = ctx.version; this._initialize(ctx) }",
  "      resolveOptions() { return this.options }",
  "      async clean() {}",
  "      onAfterSuiteRun() {}",
  "      async generateCoverage() { return {} }",
  "      async reportCoverage() {",
  "        const root = this.ctx.config.root",
  "        writeFileSync(" + JSON.stringify(outFile) + ", JSON.stringify({ component: this.isIncluded(root + '/src/component.js') }))",
  "      }",
  "    }",
  "    return new Probe()",
  "  },",
  "}",
].join("\n") + "\n");
write("vitest.config.mjs", [
  "export default {",
  "  test: {",
  "    include: ['**/*.test.mjs', '!something'],",
  "    coverage: { enabled: true, provider: 'custom', customProviderModule: './provider.mjs', include: ['src/**'] },",
  "  },",
  "}",
].join("\n") + "\n");
write("src/component.js", "export const one = 1\n");
write("math.test.mjs", "import { test, expect } from 'vitest'\ntest('one', () => { expect(1).toBe(1) })\n");
const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", "run"], {
  cwd: dir,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1" },
  timeout: 60000,
});
console.log((r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : ""));
if (!fs.existsSync(outFile)) {
  console.error("ERROR: the coverage provider never reported (exit " + r.status + ")");
  process.exit(2);
}
const result = JSON.parse(fs.readFileSync(outFile, "utf8"));
console.log("result " + JSON.stringify(result));
if (result.component === true) {
  console.log("PASS: src/component.js is covered; coverage.exclude ignores the negation glob !something from test.include");
  process.exit(0);
}
if (result.component === false) {
  console.error("FAIL: coverage.exclude inherited !something from test.include and excluded src/component.js");
  process.exit(1);
}
console.error("ERROR: unexpected result " + JSON.stringify(result));
process.exit(2);

