const fs = require("fs");
const path = require("path");
const cp = require("child_process");
const parent = "/w/ancestorcfg";
const sub = path.join(parent, "sub");
fs.rmSync(parent, { recursive: true, force: true });
fs.mkdirSync(sub, { recursive: true });
const marker = path.join(parent, "config-loaded.txt");
// A config file in the parent directory that records when vitest loads it.
fs.writeFileSync(path.join(parent, "vitest.config.mjs"), [
  "import { writeFileSync } from 'node:fs'",
  "writeFileSync(" + JSON.stringify(marker) + ", 'yes')",
  "export default {}",
].join("\n") + "\n");
fs.writeFileSync(path.join(sub, "a.test.mjs"), [
  "import { test } from 'vitest'",
  "import { writeFileSync } from 'node:fs'",
  "test('a', () => { writeFileSync(new URL('./ran.txt', import.meta.url), 'yes') })",
].join("\n") + "\n");
const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", "run"], {
  cwd: sub,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1" },
  timeout: 60000,
});
const out = (r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : "");
console.log(out);
const ran = fs.existsSync(path.join(sub, "ran.txt"));
const loaded = fs.existsSync(marker);
if (!ran || r.status !== 0) {
  console.error("ERROR: vitest did not run the test in sub (exit " + r.status + ", ran " + ran + ")");
  process.exit(2);
}
// The symptom of the old behavior: the parent directory's config file was loaded.
if (loaded) {
  console.error("FAIL: vitest run in sub loaded vitest.config.mjs from the parent directory");
  process.exit(1);
}
console.log("PASS: vitest run in sub did not load vitest.config.mjs from the parent directory");
process.exit(0);

