fs.rmSync(dir, { recursive: true, force: true });
fs.mkdirSync(dir, { recursive: true });
fs.writeFileSync(path.join(dir, "win.test.mjs"), [
  "import { test } from 'vitest'",
  "import { writeFileSync } from 'node:fs'",
  "test('innerWidth', () => {",
  "  const before = window.matchMedia('(max-width: 100px)').matches",
  "  window.innerWidth = 50",
  "  const after = window.matchMedia('(max-width: 100px)').matches",
  "  writeFileSync(new URL('./result.json', import.meta.url), JSON.stringify({ before, after, width: window.innerWidth }))",
  "})",
].join("\n") + "\n");
const r = cp.spawnSync(process.execPath, ["/w/node_modules/vitest/vitest.mjs", "run", "--environment=happy-dom"], {
  cwd: dir,
  encoding: "utf8",
  env: { ...process.env, NO_COLOR: "1", CI: "1" },
  timeout: 60000,
});
console.log((r.stdout || "") + (r.stderr || "") + (r.error ? String(r.error) : ""));
const resultFile = path.join(dir, "result.json");
if (!fs.existsSync(resultFile)) {
  console.error("ERROR: the test file wrote no result (exit " + r.status + ")");
  process.exit(2);
}
const res = JSON.parse(fs.readFileSync(resultFile, "utf8"));
console.log(JSON.stringify(res));
if (res.before !== false || res.width !== 50) {
  console.error("ERROR: unexpected result " + JSON.stringify(res));
  process.exit(2);
